        app.client.getMainProcessLogs().then(logs => {
          if (logs.length) {
            console.log('MAIN');
            let str = '';
            logs.forEach(function(log) {
              str += log + '\n';
            });
            console.log(str + '\n');
          }
        });

        app.client.getRenderProcessLogs().then(function(logs) {
          if (logs.length) {
            let str = '';
            logs.forEach(function(log) {
              if (log.level === 'ERROR') {
                str += log.level + '|' + log.message + '\n';
              }
            });
            if (str.length) {
              console.log('RENDERER');
              console.log(str + '\n');
            }
          }
        });
      }
    })

